class Animal {
    void eat() {
        System.out.println("Yum!");
    }
}

class Cat extends Animal {
    void meow() {
        System.out.println("Meow~");
    }
}

public class Main {
    public static void main(String[] args) {
        Cat myCat = new Cat();

        myCat.meow(); // 자기 기능
        myCat.eat();  // 부모 기능 (상속받음)
    }
}
